-- Lead Pipeline Transition Schema
CREATE TABLE lead_stage_transitions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  lead_id UUID NOT NULL REFERENCES leads(id) ON DELETE CASCADE,
  previous_stage VARCHAR(50) NOT NULL,
  new_stage VARCHAR(50) NOT NULL,
  transitioned_by UUID NOT NULL REFERENCES users(id),
  created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX idx_lead_transitions ON lead_stage_transitions(lead_id, created_at DESC);

